/// <summary>
///
/// </summary>
public static void createFromLinesRecord(TFMPostOrderPromptOverrideLines _lines)
{
    TFMPostOrderPromptOverrideLineFields    fields;
    MapEnumerator                           fieldsFromType = TFMPostOrderPromptOverrideLineFields::getMapFromType(_lines.InputType,0).getEnumerator();

    delete_from fields where fields.LinesRecId == _lines.RecId;
    while(fieldsFromType.moveNext())
    {

        fields.FieldName = fieldsFromType.currentKey();
        fields.Value = fieldsFromType.currentValue();
        fields.LinesRecId = _lines.RecId;
        if (fields.FieldName != 'id' && fields.FieldName != 'name' && fields.FieldName != 'inputType')
        {
            fields.insert();
        }
    }

}

public static Map getMapFromType(TFMInputTypes _inputTypes, int _id, str _name = 'name', str _header = 'header', str _label = 'label', str _helpText = 'helpText', str _defaultValue = 'Value1', str _steps = 'Value1;Value2;etc')
{
    return TFMPostOrderPromptOverrideLineFields::getStepFromType(_inputTypes, _id, _name, _header, _label, _helpText, _defaultValue, _steps).getMap();        
}

public static TFMRegistrationCollector getStepFromType(TFMInputTypes _inputTypes, int _id, str _name = 'name', str _header = 'header', str _label = 'label', str _helpText = 'helpText', str _defaultValue = 'Value1', str _steps = 'Value1;Value2;etc')
{
    TFMRegistrationCollector ret;
    switch ( _inputTypes)
    {
        case TFMInputTypes::Date :
            ret = TFMRegistrationCollectorDate::DateStep(true,_id,_name,_header,_label,_helpText,dateNull(),dateMax());
            break;
        case TFMInputTypes::Decimal :
            ret = TFMRegistrationCollectorDecimal::DecimalStep(_id,_name,_header,_label, _helpText);
            break;
        case TFMInputTypes::Image :
            ret = new TFMRegistrationCollectorImage(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::ImageCapture :
            ret = new TFMRegistrationCollectorImageCapture(_id,_name,_label,_header,_helpText);
            break;
        case TFMInputTypes::Information :
            ret = new TFMRegistrationCollectorInformation(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::Integer :
            ret = TFMRegistrationCollectorInteger::IntegerStep(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::List :
            ret = TFMRegistrationCollectorList::ListStep(true,_id,_name,_label,_header, _helpText,_steps);
            break;
        case TFMInputTypes::MultiLineText :
            ret = new TFMRegistrationCollectorMultiLine(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::MultiScan : 
            ret = new TFMRegistrationCollectorMultiScan(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::QuantityByScan :
            ret = TFMRegistrationCollectorQuantityByScan::QtyByScanStep(_id,_name,_label,_header, _helpText,_steps);
            break;
        case TFMInputTypes::RadioButton :
            ret = TFMRegistrationCollectorRadioButton::RadioButtonStep(_id,_name,_label,_header, _helpText,_defaultValue,_steps);
            break;
        case TFMInputTypes::Signature :
            ret = TFMRegistrationCollectorSignature::SignatureStep(_id,_name,_label,_header, _helpText);
            break;
        case TFMInputTypes::Text :
            ret = TFMRegistrationCollectorText::TextStep(true,_id,_name,_label,_header, _helpText,100);
            break;
        case TFMInputTypes::TypeAndQuantity : 
            ret = TFMRegistrationCollectorTypeAndQuantity::TypeAndQuantity(_id,_name,_label,_header, _helpText);
            break;
    }
    ret.parmDefaultValue(_defaultValue);
    return ret;
}
